const StockGeneratorGroup *stockGeneratorGroup(const QString &pluginId)
{
    for (const StockGeneratorGroup &g : stockGeneratorPresets()) {
        if (g.pluginId.compare(pluginId, Qt::CaseInsensitive) == 0) {
            return &g;
        }
    }
    return nullptr;
}

const StockGeneratorPreset *stockGeneratorPreset(const QString &pluginId, const QString &presetName)
{
    const StockGeneratorGroup *group = stockGeneratorGroup(pluginId);
    if (!group) {
        return nullptr;
    }
    for (const StockGeneratorPreset &p : group->presets) {
        if (p.name.compare(presetName, Qt::CaseInsensitive) == 0) {
            return &p;
        }
    }
    return nullptr;
}

